/**
 * tasks.ts — task list core logic.
 *
 * Display order is NEWEST FIRST (id desc). `done <n>` takes the 1-based
 * index as shown by `list`.
 *
 * NOTE: completeTask below contains a subtle planted bug for the benchmark:
 * it indexes the raw insertion-ordered array instead of the displayed
 * (sorted, filtered) list, so `done 1` completes the wrong task whenever
 * two or more tasks exist.
 */

import { type Task, loadTasks, saveTasks, nextId } from "./storage.ts";

/** Tasks as the user sees them: incomplete first? No — newest first, done hidden unless all=true. */
export function visibleTasks(tasks: Task[], all = false): Task[] {
  const filtered = all ? tasks : tasks.filter((t) => !t.done);
  return [...filtered].sort((a, b) => b.id - a.id);
}

export function addTask(title: string, file?: string): Task {
  const tasks = loadTasks(file);
  const task: Task = { id: nextId(tasks), title, done: false, createdAt: new Date().toISOString() };
  tasks.push(task);
  saveTasks(tasks, file);
  return task;
}

export function listTasks(all = false, file?: string): Task[] {
  return visibleTasks(loadTasks(file), all);
}

/** Complete the task at 1-based display index n (as shown by `list`). */
export function completeTask(n: number, file?: string): Task {
  const tasks = loadTasks(file);
  // PLANTED BUG: indexes the unsorted, unfiltered array instead of visibleTasks().
  const task = tasks[n - 1];
  if (!task) throw new Error(`no task at index ${n}`);
  task.done = true;
  saveTasks(tasks, file);
  return task;
}

/**
 * cli.ts — tiny JSON task-list CLI.
 *   node src/cli.ts add "title"     → prints "added <id>. <title>"
 *   node src/cli.ts list [--all] [--json]
 *   node src/cli.ts done <n>        → prints "done <id>. <title>"
 */

import { addTask, listTasks, completeTask } from "./tasks.ts";
import { loadTasksFast } from "./cache.ts";
import { storageFile } from "./storage.ts";
import { visibleTasks } from "./tasks.ts";

function formatTask(t: { id: number; title: string; done: boolean }): string {
  return `${t.done ? "[x]" : "[ ]"} ${t.id}. ${t.title}`;
}

function main(argv: string[]): void {
  const [cmd, ...rest] = argv;
  const file = storageFile();
  switch (cmd) {
    case "add": {
      const title = rest.join(" ");
      const task = addTask(title, file);
      console.log(`added ${task.id}. ${task.title}`);
      break;
    }
    case "list": {
      const all = rest.includes("--all");
      const asJson = rest.includes("--json");
      const tasks = visibleTasks(loadTasksFast(file), all);
      if (asJson) console.log(JSON.stringify(tasks));
      else for (const t of tasks) console.log(formatTask(t));
      break;
    }
    case "done": {
      const n = parseInt(rest[0] ?? "", 10);
      const task = completeTask(n, file);
      console.log(`done ${task.id}. ${task.title}`);
      break;
    }
    default:
      console.log("usage: cli.ts add <title> | list [--all] [--json] | done <n>");
  }
}

main(process.argv.slice(2));

import assert from "node:assert";
import test from "node:test";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { addTask, listTasks } from "../src/tasks.ts";
import { loadTasks, nextId } from "../src/storage.ts";

function tmpFile(): string {
  return path.join(mkdtempSync(path.join(tmpdir(), "tasks-test-")), "tasks.json");
}

test("add + list shows newest first", () => {
  const f = tmpFile();
  addTask("first", f);
  addTask("second", f);
  const list = listTasks(false, f);
  assert.strictEqual(list.length, 2);
  assert.strictEqual(list[0].title, "second");
  assert.strictEqual(list[1].title, "first");
});

test("nextId increments past max id", () => {
  assert.strictEqual(nextId([]), 1);
  assert.strictEqual(nextId([{ id: 3, title: "x", done: false, createdAt: "" }]), 4);
});

test("done tasks are hidden from default list", async () => {
  const f = tmpFile();
  addTask("keep", f);
  const t2 = addTask("hide me", f);
  const tasks = loadTasks(f);
  tasks.find((t) => t.id === t2.id)!.done = true;
  const { saveTasks } = await import("../src/storage.ts");
  saveTasks(tasks, f);
  const list = listTasks(false, f);
  assert.deepStrictEqual(list.map((t) => t.title), ["keep"]);
});

/**
 * storage.ts — JSON file persistence for the task list.
 * Storage file path comes from TASKS_FILE env or ./tasks.json.
 */

import { readFileSync, writeFileSync, renameSync, existsSync } from "node:fs";

export interface Task {
  id: number;
  title: string;
  done: boolean;
  createdAt: string;
}

export function storageFile(): string {
  return process.env.TASKS_FILE || "tasks.json";
}

export function loadTasks(file: string = storageFile()): Task[] {
  if (!existsSync(file)) return [];
  const raw = readFileSync(file, "utf8").trim();
  if (raw === "") return [];
  return JSON.parse(raw) as Task[];
}

export function saveTasks(tasks: Task[], file: string = storageFile()): void {
  const tmp = file + ".tmp";
  writeFileSync(tmp, JSON.stringify(tasks, null, 2) + "\n", "utf8");
  renameSync(tmp, file);
}

export function nextId(tasks: Task[]): number {
  return tasks.reduce((m, t) => Math.max(m, t.id), 0) + 1;
}

